import{_ as e,o as s,c as o,ag as n}from"./chunks/framework.1IVNT0ce.js";const F=JSON.parse('{"title":"Error Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),r={name:"reference/errors.md"};function l(t,a,p,c,i,d){return s(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="error-reference" tabindex="-1">Error Reference <a class="header-anchor" href="#error-reference" aria-label="Permalink to &quot;Error Reference&quot;">​</a></h1><p>Klix defines a small set of framework-level exceptions. Most apps do not need to raise all of them directly, but understanding what they mean helps when you build custom flows or debugging tools.</p><h2 id="klixerror" tabindex="-1"><code>KlixError</code> <a class="header-anchor" href="#klixerror" aria-label="Permalink to &quot;`KlixError`&quot;">​</a></h2><p>Base class for framework exceptions.</p><p>If you need to catch “framework-specific” errors broadly, catch this type.</p><h2 id="commandnotfounderror" tabindex="-1"><code>CommandNotFoundError</code> <a class="header-anchor" href="#commandnotfounderror" aria-label="Permalink to &quot;`CommandNotFoundError`&quot;">​</a></h2><p>Raised when the router cannot resolve the first token to a registered command or alias.</p><p>Typical cause:</p><ul><li>user typed an unknown slash command</li></ul><p>The default app loop catches this and prints an error line.</p><h2 id="argvalidationerror" tabindex="-1"><code>ArgValidationError</code> <a class="header-anchor" href="#argvalidationerror" aria-label="Permalink to &quot;`ArgValidationError`&quot;">​</a></h2><p>Raised when parsed arguments do not satisfy the command schema.</p><p>Constructor fields:</p><ul><li><code>field</code></li><li><code>message</code></li></ul><p>String form:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Validation failed for field &#39;&lt;field&gt;&#39;: &lt;message&gt;</span></span></code></pre></div><p>Use this when you need structured command argument failure reporting.</p><h2 id="inputcancellederror" tabindex="-1"><code>InputCancelledError</code> <a class="header-anchor" href="#inputcancellederror" aria-label="Permalink to &quot;`InputCancelledError`&quot;">​</a></h2><p>Raised when an interactive input component is cancelled rather than completed.</p><p>Most common sources:</p><ul><li><code>select(...)</code></li><li><code>multiselect(...)</code></li><li><code>fuzzy(...)</code></li></ul><p>If cancellation is part of your normal UX, catch it and respond cleanly.</p><h2 id="sessionstateerror" tabindex="-1"><code>SessionStateError</code> <a class="header-anchor" href="#sessionstateerror" aria-label="Permalink to &quot;`SessionStateError`&quot;">​</a></h2><p>Used for session state and persistence-related failures.</p><p>This is the right category when serialization, reconstruction, or state integrity fails.</p><h2 id="middlewareaborterror" tabindex="-1"><code>MiddlewareAbortError</code> <a class="header-anchor" href="#middlewareaborterror" aria-label="Permalink to &quot;`MiddlewareAbortError`&quot;">​</a></h2><p>Represents middleware-aborted execution. The current middleware pattern usually relies on <code>ctx.cancelled</code> and early returns instead of explicitly raising this, but the type exists in the public error surface.</p><h2 id="rendererror" tabindex="-1"><code>RenderError</code> <a class="header-anchor" href="#rendererror" aria-label="Permalink to &quot;`RenderError`&quot;">​</a></h2><p>Used for rendering failures or renderer-specific issues.</p><h2 id="compatibilityerror" tabindex="-1"><code>CompatibilityError</code> <a class="header-anchor" href="#compatibilityerror" aria-label="Permalink to &quot;`CompatibilityError`&quot;">​</a></h2><p>Used when terminal or environment compatibility checks fail.</p><p>This is more relevant to renderer-selection and environment adaptation code than to normal app handlers.</p><h2 id="practical-error-handling-pattern" tabindex="-1">Practical Error Handling Pattern <a class="header-anchor" href="#practical-error-handling-pattern" aria-label="Permalink to &quot;Practical Error Handling Pattern&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#BABED8;"> klix </span><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> InputCancelledError</span></span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/wizard</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Run interactive setup</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>\n<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> wizard</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>\n<span class="line"><span style="color:#89DDFF;font-style:italic;">    try</span><span style="color:#89DDFF;">:</span></span>\n<span class="line"><span style="color:#BABED8;">        choice </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">select</span><span style="color:#89DDFF;">(</span></span>\n<span class="line"><span style="color:#89DDFF;">            [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">staging</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">production</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">],</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">            label</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Choose target</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#89DDFF;">        )</span></span>\n<span class="line"><span style="color:#89DDFF;font-style:italic;">    except</span><span style="color:#BABED8;"> InputCancelledError</span><span style="color:#89DDFF;">:</span></span>\n<span class="line"><span style="color:#BABED8;">        session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Setup cancelled.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">warning</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>\n<span class="line"><span style="color:#89DDFF;font-style:italic;">        return</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#C792EA;">f</span><span style="color:#C3E88D;">&quot;Selected </span><span style="color:#F78C6C;">{</span><span style="color:#82AAFF;">choice</span><span style="color:#F78C6C;">}</span><span style="color:#C3E88D;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">success</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Catching raw <code>Exception</code> everywhere instead of handling framework-level failures deliberately.</li><li>Treating <code>CommandNotFoundError</code> as a fatal application error in custom loops.</li><li>Forgetting that cancellation is not necessarily an error from the user’s perspective.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./commands">Reference: Commands</a></li><li><a href="./middleware">Reference: Middleware</a></li><li><a href="./../faq">FAQ</a></li></ul>',38)])])}const D=e(r,[["render",l]]);export{F as __pageData,D as default};
